CREATE TABLE runtime_instance(id boolean PRIMARY KEY DEFAULT true CHECK(id),turn bigint NOT NULL DEFAULT 0,active_missions integer NOT NULL DEFAULT 0 CHECK(active_missions>=0),active_agents integer NOT NULL DEFAULT 0 CHECK(active_agents>=0),storage_bytes bigint NOT NULL DEFAULT 0 CHECK(storage_bytes>=0));
INSERT INTO runtime_instance(id) VALUES(true);
CREATE TABLE runtime_tenants(organization_id uuid PRIMARY KEY REFERENCES organizations(id),turn bigint NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE runtime_instance_hours(window_start timestamptz PRIMARY KEY,tool_calls integer NOT NULL DEFAULT 0 CHECK(tool_calls>=0),runtime_ms integer NOT NULL DEFAULT 0 CHECK(runtime_ms>=0));
CREATE TABLE runtime_quota_scopes(organization_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('organization','user','project')),scope_id uuid NOT NULL,limits jsonb NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),active_missions integer NOT NULL DEFAULT 0 CHECK(active_missions>=0),active_agents integer NOT NULL DEFAULT 0 CHECK(active_agents>=0),storage_bytes bigint NOT NULL DEFAULT 0 CHECK(storage_bytes>=0),PRIMARY KEY(organization_id,kind,scope_id));
CREATE TABLE runtime_quota_hours(organization_id uuid NOT NULL,kind text NOT NULL,scope_id uuid NOT NULL,window_start timestamptz NOT NULL,tool_calls integer NOT NULL DEFAULT 0 CHECK(tool_calls>=0),runtime_ms integer NOT NULL DEFAULT 0 CHECK(runtime_ms>=0),PRIMARY KEY(organization_id,kind,scope_id,window_start),FOREIGN KEY(organization_id,kind,scope_id) REFERENCES runtime_quota_scopes(organization_id,kind,scope_id));
CREATE TABLE runtime_storage_reservations(organization_id uuid NOT NULL,resource_id uuid NOT NULL,bytes bigint NOT NULL CHECK(bytes>0),scopes jsonb NOT NULL,PRIMARY KEY(organization_id,resource_id));
CREATE TABLE runtime_admissions(organization_id uuid NOT NULL,mission_id uuid NOT NULL,scopes jsonb NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(organization_id,mission_id),FOREIGN KEY(organization_id,mission_id) REFERENCES runtime_missions(organization_id,id));
CREATE TABLE runtime_attempt_quotas(organization_id uuid NOT NULL,attempt_id uuid NOT NULL,scopes jsonb NOT NULL,active boolean NOT NULL DEFAULT true,tool_calls integer NOT NULL,runtime_ms integer NOT NULL,window_start timestamptz NOT NULL,PRIMARY KEY(organization_id,attempt_id),FOREIGN KEY(organization_id,attempt_id) REFERENCES runtime_attempts(organization_id,id));
CREATE TABLE runtime_outbox(id uuid PRIMARY KEY,organization_id uuid NOT NULL,mission_id uuid NOT NULL,task_id uuid NOT NULL,generation integer NOT NULL CHECK(generation>0),created_at timestamptz NOT NULL,lease_id uuid,lease_expires_at timestamptz,published_at timestamptz,next_publish_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),FOREIGN KEY(organization_id,mission_id,task_id) REFERENCES runtime_tasks(organization_id,mission_id,id));
CREATE INDEX runtime_outbox_pending ON runtime_outbox(organization_id,next_publish_at,created_at,id) WHERE published_at IS NULL;
CREATE INDEX runtime_outbox_task ON runtime_outbox(organization_id,task_id,generation,published_at);
ALTER TABLE runtime_instance ENABLE ROW LEVEL SECURITY;
ALTER TABLE runtime_instance FORCE ROW LEVEL SECURITY;
CREATE POLICY runtime_instance_internal ON runtime_instance USING(current_setting('app.runtime_internal',true)='enabled') WITH CHECK(current_setting('app.runtime_internal',true)='enabled');
GRANT SELECT,INSERT,UPDATE ON runtime_instance TO craftlayer_runtime;
ALTER TABLE runtime_tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE runtime_tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY runtime_tenants_internal ON runtime_tenants USING(current_setting('app.runtime_internal',true)='enabled') WITH CHECK(current_setting('app.runtime_internal',true)='enabled');
GRANT SELECT,INSERT,UPDATE ON runtime_tenants TO craftlayer_runtime;
